Likutay Halachos — Orach Chaim Vol. 3 — Hilchos Shabbos 7

:root{--bg:#faf6ef;--text:#2a2118;--accent:#8b6914;--accent-light:#c9a84c;--accent-dark:#5a4510;--verse-bg:#ede4cf;--verse-border:#c9a84c;--subtitle-bg:#f5eed8;--key-color:#6b3a2a;--source-color:#555;--divider:#d4c5a0;--summary-bg:#eef4ec;--summary-border:#7a9e6d;--fc-bg:#fdfcf8;--fc-border:#c9a84c;--fc-node:#f5eed8;--fc-arrow:#8b6914}

*{margin:0;padding:0;box-sizing:border-box}

body{background:var(--bg);color:var(--text);font-family:'EB Garamond','Cormorant Garamond',Georgia,serif;font-size:18px;line-height:1.85}

.pw{max-width:780px;margin:0 auto;padding:40px 30px 80px}

.bt{text-align:center;margin-bottom:50px;padding:40px 20px 35px;border-top:3px double var(--accent);border-bottom:3px double var(--accent);background:linear-gradient(180deg,transparent 0%,rgba(201,168,76,.06) 50%,transparent 100%)}

.bt h1{font-family:'Cormorant Garamond',Georgia,serif;font-weight:700;font-size:32px;letter-spacing:3px;text-transform:uppercase;color:var(--accent-dark);margin-bottom:6px}

.bt .vol{font-family:'EB Garamond',serif;font-size:17px;font-style:italic;color:var(--accent);letter-spacing:1.5px}

.hh{text-align:center;margin:55px 0 10px}

.hh h2{font-family:'Cormorant Garamond',Georgia,serif;font-weight:600;font-size:26px;color:var(--accent-dark);letter-spacing:2px}

.hh .hd{display:block;width:80px;height:2px;background:var(--accent-light);margin:10px auto 0}

.hs{text-align:center;margin:5px 0 30px;padding:12px 25px;background:var(--subtitle-bg);border-radius:4px;font-family:'Cormorant Garamond',Georgia,serif;font-size:19px;font-weight:500;color:var(--accent-dark);font-style:italic;line-height:1.65}

.sl{text-align:center;margin-bottom:25px;padding:10px 20px;font-size:16.5px;color:var(--source-color);font-style:italic;line-height:1.7;border-left:3px solid var(--divider);border-right:3px solid var(--divider);background:rgba(201,168,76,.03)}

p.p{text-align:justify;margin-bottom:22px;text-indent:2em;hyphens:auto}

.kt{color:var(--key-color);font-weight:600;font-style:italic}

.kd{font-size:.88em;color:var(--source-color);font-style:normal;font-weight:400}

.v{font-style:italic;color:var(--accent-dark);font-weight:500}

.vs{font-size:.85em;color:var(--source-color);font-style:normal;font-weight:400}

.ar{font-style:italic;color:#5a3d2b}

.sp{font-style:italic;text-decoration:underline;text-decoration-color:var(--accent-light);text-underline-offset:3px}

.sb{text-align:center;margin:40px 0;color:var(--accent-light);font-size:20px;letter-spacing:12px}

.sq{font-weight:500;color:#4a3520}

.sn{text-align:center;margin:40px 0 20px;font-family:'Cormorant Garamond',Georgia,serif;font-weight:600;font-size:20px;color:var(--accent);letter-spacing:1px}

.sn span{display:inline-block;padding:4px 18px;border-bottom:2px solid var(--accent-light)}

.np{font-family:'EB Garamond',serif;font-weight:700;color:var(--accent-dark);background:rgba(201,168,76,.15);padding:1px 5px;border-radius:3px}

.ts{margin:45px 0 25px;padding:25px 28px;background:var(--summary-bg);border:1px solid var(--summary-border);border-radius:6px}

.ts .th{font-family:'Cormorant Garamond',Georgia,serif;font-size:15px;font-weight:600;text-transform:uppercase;letter-spacing:2px;color:var(--summary-border);margin-bottom:12px;padding-bottom:8px;border-bottom:1px solid rgba(122,158,109,.3)}

.ts p{font-size:16px;line-height:1.75;color:#3a4a35;text-align:justify;margin-bottom:10px}

.ts p:last-child{margin-bottom:0}

.fc{margin:30px 0;padding:25px 20px;background:var(--fc-bg);border:1px solid var(--fc-border);border-radius:8px;text-align:center}

.fc .ft{font-family:'Cormorant Garamond',Georgia,serif;font-size:15px;font-weight:600;text-transform:uppercase;letter-spacing:2px;color:var(--accent);margin-bottom:18px}

.fr{display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:8px;margin-bottom:10px}

.fn{background:var(--fc-node);border:1px solid var(--divider);border-radius:6px;padding:8px 16px;font-size:15px;font-family:'EB Garamond',serif;color:var(--accent-dark);line-height:1.5;max-width:220px}

.fn.hi{background:var(--accent-light);color:#fff;font-weight:600;border-color:var(--accent-dark)}

.fa{color:var(--fc-arrow);font-size:20px;font-weight:700}

.fa.dn{display:block;text-align:center;margin:4px 0;font-size:22px}

@media(max-width:600px){.pw{padding:25px 18px 60px}body{font-size:17px}.bt h1{font-size:24px}.hh h2{font-size:22px}.fr{flex-direction:column}}

